import { Request, Response, Router } from 'express';
import { AddTaskUseCase } from '../../../application/task/AddTaskUseCase';
import { AssignTaskUseCase } from '../../../application/task/AssignTaskUseCase';
import { CompleteTaskUseCase } from '../../../application/task/CompleteTaskUseCase';
import { ListTasksUseCase } from '../../../application/task/ListTasksUseCase';
import { asFields, optionalString, requiredString } from '../requestFields';

export class TaskController {
  readonly router = Router();

  constructor(
    private readonly addTask: AddTaskUseCase,
    private readonly listTasks: ListTasksUseCase,
    private readonly assignTask: AssignTaskUseCase,
    private readonly completeTask: CompleteTaskUseCase,
  ) {
    this.router.post('/projects/:projectId/tasks', this.add);
    this.router.get('/projects/:projectId/tasks', this.list);
    this.router.put('/tasks/:taskId/assignee', this.assign);
    this.router.post('/tasks/:taskId/complete', this.complete);
  }

  private readonly add = async (req: Request, res: Response): Promise<void> => {
    const body = asFields(req.body);
    const task = await this.addTask.execute({
      projectId: requiredString(asFields(req.params), 'projectId'),
      title: requiredString(body, 'title'),
      description: optionalString(body, 'description') ?? '',
      dueDate: optionalString(body, 'dueDate'),
      status: optionalString(body, 'status'),
    });
    res.status(201).json(task);
  };

  private readonly list = async (req: Request, res: Response): Promise<void> => {
    const query = asFields(req.query);
    const tasks = await this.listTasks.execute({
      projectId: requiredString(asFields(req.params), 'projectId'),
      status: optionalString(query, 'status'),
      assigneeId: optionalString(query, 'assigneeId'),
    });
    res.json(tasks);
  };

  private readonly assign = async (req: Request, res: Response): Promise<void> => {
    const body = asFields(req.body);
    const task = await this.assignTask.execute({
      taskId: requiredString(asFields(req.params), 'taskId'),
      userId: requiredString(body, 'userId'),
    });
    res.json(task);
  };

  private readonly complete = async (req: Request, res: Response): Promise<void> => {
    res.json(await this.completeTask.execute({ taskId: requiredString(asFields(req.params), 'taskId') }));
  };
}

